import math

def get_primes(n):
    primes = []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    p = 2
    while p <= math.sqrt(n):
        if sieve[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                sieve[i] = False
        p += 1
    return primes

def maximum_subarray_sum(my_array, start_row, end_row, start_col, end_col):
    primes = get_primes(10**9)
    prefix_sum = [[0] * (len(my_array[0]) + 1) for _ in range(len(my_array) + 1)]
    for i in range(1, len(my_array) + 1):
        for j in range(1, len(my_array[0]) + 1):
            prefix_sum[i][j] = prefix_sum[i - 1][j] + prefix_sum[i][j - 1] - prefix_sum[i - 1][j - 1] + my_array[i - 1][j - 1]

    max_sum = float('-inf')
    for i in range(start_row, end_row + 1):
        for j in range(start_col, end_col + 1):
            for k in range(i, end_row + 1):
                for l in range(j, end_col + 1):
                    subarray_sum = prefix_sum[k + 1][l + 1] - prefix_sum[i][l + 1] - prefix_sum[k + 1][j] + prefix_sum[i][j]
                    if subarray_sum % 2 != 0 and subarray_sum % primes[0] == 0:
