                primes.append(num)


        composites = []
        while len(composites) < 2:
            num = random.randint(min_range, max_range)
            if num % 2 == 0 and not isprime(num):  
                composites.append(num)


        self.grid = [[None, None, None],
                     [None, None, None],
                     [None, None, None]]


        self.grid[0][0] = primes[0]
        self.grid[0][1] = primes[1]
        self.grid[0][2] = composites[0]
        self.grid[1][0] = primes[2]
        self.grid[1][1] = composites[1]
        self.grid[1][2] = None
        self.grid[2][0] = None
        self.grid[2][1] = None
        self.grid[2][2] = None

    def check_condition(self):

        odd_primes_count = 0
        even_composites_count = 0

        for i in range(3):
            for j in range(3):
                if self.grid[i][j] is not None:
                    if isprime(self.grid[i][j]) or self.grid[i][j] % 2 != 0:  
                        odd_primes_count += 1
                    elif not isprime(self.grid[i][j]) and self.grid[i][j] % 2 == 0:
                        even_composites_count += 1

        return odd_primes_count == 3 and even_composites_count == 2

    def swap_numbers(self, pos1, pos2):

        if not self._is_valid_position(pos1) or not self._is_valid_position(pos2):
            print("Invalid positions.")
            return None  


        temp = self.grid[pos1[0]][pos1[1]]
        self.grid[pos1[0]][pos1[1]] = self.grid[pos2[0]][pos2[1]]
        self.grid[pos2[0]][pos2[1]] = temp

    def print_grid(self):
        if self.grid is None:
            print("Grid is not initialized.")
            return None  

        for i in range(3):
            for j in range(3):
                if self.grid[i][j] is None:
                    print("  ", end="")
                else:
                    print(self.grid[i][j], end=" ")
            print()

    def _is_valid_position(self, pos):
        return 0 <= pos[0] < 3 and 0 <= pos[1] < 3


