import random

def shuffle_sequence(sequence):
    n = len(sequence)
    for i in range(n - 1):
        j = random.randint(i, n - 1)
        sequence[i], sequence[j] = sequence[j], sequence[i]

def quicksort(sequence):
    if len(sequence) <= 1:
        return sequence
    pivot = sequence[0]
    less_than_pivot = [x for x in sequence[1:] if x <= pivot]
    greater_than_pivot = [x for x in sequence[1:] if x > pivot]
    return quicksort(less_than_pivot) + [pivot] + quicksort(greater_than_pivot)

def find_median(sequence):
    shuffle_sequence(sequence)
    sorted_sequence = quicksort(sequence)
    n = len(sorted_sequence)
    if n % 2 == 1:
        return sorted_sequence[n // 2]
    else:
        mid_index = n // 2
        return (sorted_sequence[mid_index - 1] + sorted_sequence[mid_index]) / 2

