            if session['task'] == task:
                session['start_time'] = start_time
                session['end_time'] = end_time
        new_session = {'start_time': start_time, 'end_time': end_time, 'task': task}
        self.employees[employee_id].work_sessions.append(new_session)

    def calculate_total_work_hours(self, employee_id):
        total_hours = 0
        for session in self.employees[employee_id].work_sessions:
            start_time = datetime.strptime(session['start_time'], '%H:%M')
            end_time = datetime.strptime(session['end_time'], '%I:%S')
            total_hours += (end_time - start_time).total_seconds() / 3600
        return total_hours

