def validate_credit_card(card_number):
    # Remove any whitespace characters from the card number
    card_number = card_number.replace(" ", "")

    # Check if the card number contains any non-numeric characters
    if not card_number.isdigit():
        return "Invalid input"

    # Check if the card number is a valid Visa card
    if card_number[0] == '4' and (len(card_number) == 13 or len(card_number) == 16) and sum_digits(card_number) % 10 == 0:
        return "Visa"

    # Check if the card number is a valid Mastercard
    if card_number[0] == '5' and len(card_number) == 16 and sum_even_indexed_digits(card_number) == sum_odd_indexed_digits(card_number):
        return "Mastercard"

    # Check if the card number is a valid American Express card
    if card_number[:2] == '34' or card_number[:2] == '37' and len(card_number) == 15 and card_number == card_number[::-1]:
        return "American Express"

    # Return "Invalid input" if the card number does not match any of the criteria
    return "Invalid input"


def sum_digits(card_number):
    # Calculate the sum of all digits in the card number
    return sum(int(digit) for digit in card_number)


def sum_even_indexed_digits(card_number):
    # Calculate the sum of the squares of all even-indexed digits in the card number
    return sum(int(digit)**2 for i, digit in enumerate(card_number) if i % 2 == 0)


def sum_odd_indexed_digits(card_number):
    # Calculate the sum of the cubes of all odd-indexed digits in the card number
    return sum(int(digit)**3 for i, digit in enumerate(card_number) if i % 2 != 0)


